-- data_029_of_120.sql: intelligence dataset 2026-09-29, part 29 of 120. Run in order; safe to re-run.

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--aston-villa', 'Aston Villa Football Club', 'Aston Villa', 'football', 'Premier League', 'England', 'Birmingham', 'Villa Park', 43205, 'https://en.wikipedia.org/wiki/Villa_Park', 1874, 'avfc.co.uk', 'consortium', 'Aston Villa is 100% owned by V Sports (formerly NSWE), the Luxembourg-based holding company of Egyptian billionaire Nassef Sawiris and US billionaire Wes Edens, who bought 55% of the club in July 2018 and the remainder in August 2019. Comcast-backed investment firm Atairos joined V Sports as a minority partner in 2023-24 and holds roughly a third of the holding company; V Sports states it retains full control of all club decisions.', 'https://en.wikipedia.org/wiki/V_Sports', 378000000, 'GBP', '2024-25', 'The Swiss Ramble (Aston Villa Finances 2024/25)', 'https://swissramble.substack.com/p/aston-villa-finances-202425', 1400000000, 'USD', 2025, 'Forbes', 'https://www.forbes.com/teams/aston-villa/', 15800000, 'June 2025', 'https://www.avillafan.com/40327/villas-global-fanbase-how-aston-villa-became-a-worldwide-brand/', '[{"platform": "Instagram", "followers": 5000000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/astonvilla/"}, {"platform": "Facebook", "followers": 6600000, "as_of": "June 2025", "source_url": "https://www.avillafan.com/40327/villas-global-fanbase-how-aston-villa-became-a-worldwide-brand/"}, {"platform": "TikTok", "followers": 4300000, "as_of": "June 2025", "source_url": "https://www.avillafan.com/40327/villas-global-fanbase-how-aston-villa-became-a-worldwide-brand/"}]'::jsonb, 'Ownership percentages for Sawiris, Edens and Atairos are stakes in the holding company V Sports, not direct club stakes; V Sports owns 100% of AVFC and states it retains full control. Atairos''s stake is reported as ~31.1% (Oct 2024/Nov 2025) and rounded to 32% in Wikipedia''s ownership split; the amount Atairos invested was not disclosed in sources found. Revenue: 2024-25 club record of £378m (Deloitte Money League 2026 ranks Villa 14th, €450.2m); 2025-26 accounts not yet found. Valuation: Forbes May 2025 $1.4bn (16th); Forbes and CNBC published 2026 lists on 29 May 2026 (CNBC ranks Villa 21st, revenue $486m, EBITDA -$50m, debt 9% of value) but the 2026 dollar value did not appear in search results, so 2025 is recorded. Sportico put the club ''north of £1bn ($1.27bn)'' in 2025 without a precise figure. The women''s team sale to the parent company (~£55m) was a PSR-driven intra-group transaction and is disputed as a ''loophole'' by critics. Villa Park North Stand redevelopment is under way: capacity drops to ~37,000 for 2026-27 and rises to 50,000+ from 2027-28; 2025 accounts show a £106m facility made available to a subsidiary but undrawn. V Sports also bought 30% of FC Annecy (Ligue 2) in 2026 at a ~€15m valuation as part of its multi-club model (not a club-level deal, excluded from deals).', '["https://en.wikipedia.org/wiki/V_Sports", "https://en.wikipedia.org/wiki/Aston_Villa_F.C.", "https://en.wikipedia.org/wiki/Villa_Park", "https://www.avfc.co.uk/news/2023/december/15/v-sports-announces-investment-from-atairos/", "https://www.atairos.com/aston-villa-fc-club-statement/", "https://www.davispolk.com/experience/atairos-investment-parent-company-aston-villa-football-club", "https://www.bloomberg.com/news/articles/2018-07-20/billionaire-sawiris-wes-edens-to-buy-aston-villa-club-stake", "https://www.bloomberg.com/news/articles/2023-12-15/aston-villa-parent-sells-minority-stake-to-ex-comcast-executive", "https://enterprise.press/stories/2018/07/24/sawiris-fortress-investments-edens-acquire-55-stake-in-aston-villa-fc-in-gbp-30-mn-transaction/", "https://swissramble.substack.com/p/aston-villa-finances-202425", "https://www.deloitte.com/uk/en/services/consulting-financial/analysis/deloitte-football-money-league.html", "https://www.forbes.com/teams/aston-villa/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.cnbc.com/2026/05/29/aston-villa-2026-cnbc-global-soccer-valuations.html", "https://www.sportico.com/leagues/soccer/2025/aston-villa-champions-league-revenue-1234841606/", "https://insidersport.com/2025/07/03/aston-villa-psr-football-sale-women/", "https://www.avfc.co.uk/news/2025/october/21/investment-made-into-aston-villa-women/", "https://www.avillafan.com/40327/villas-global-fanbase-how-aston-villa-became-a-worldwide-brand/", "https://www.instagram.com/astonvilla/", "https://www.coliseum-online.com/villa-park-north-stand-redevelopment-gets-underway/", "https://www.getfootballnewsfrance.com/2026/official-aston-villas-owners-buy-minority-stake-in-annecy/"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;
